pub fn pinned_revisions(config: &SuiteConfig) -> PinnedRevisions {
    PinnedRevisions {
        ecma262: "ecma262-current-draft".to_string(),
        test262: suite_test262_pin(&config.suite_root),
    }
}

pub fn discover_suite(config: &SuiteConfig, filter: Option<&str>) -> Result<SuiteManifest, String> {
    let test_root = config.suite_root.join("test");
    if !test_root.exists() {
        return Err(format!(
            "vendored Test262 suite not found at {}",
            test_root.display()
        ));
    }

    let filter = filter.map(|value| {
        value
            .trim_start_matches("test/")
            .trim_end_matches('/')
            .to_string()
    });
    let mut cases = Vec::new();
    scan_tests(&test_root, &test_root, filter.as_deref(), &mut cases)?;
    cases.sort_by(|left, right| left.path.cmp(&right.path));

    let pinned_revisions = pinned_revisions(config);
    let manifest_hash = hash_manifest(&pinned_revisions, &cases, filter.as_deref());

    Ok(SuiteManifest {
        pinned_revisions,
        manifest_hash,
        filter,
        cases,
    })
}

pub fn load_preludes(config: &SuiteConfig) -> Result<PreludeStore, String> {
    let mut store = PreludeStore::default();

    if config.local_harness_path.exists() {
        let merged = fs::read_to_string(&config.local_harness_path).map_err(|err| {
            format!(
                "failed to read local harness {}: {err}",
                config.local_harness_path.display()
            )
        })?;
        for section in merged.split("///").skip(1) {
            let mut lines = section.lines();
            let Some(name) = lines.next() else {
                continue;
            };
            let key = name.trim().to_string();
            let mut body = lines.collect::<Vec<_>>().join("\n");
            body.push('\n');
            store.insert(key, body, PreludeOrigin::LocalMerged);
        }
    }

    let vendored_harness_root = config.suite_root.join("harness");
    if vendored_harness_root.exists() {
        let mut files = Vec::new();
        scan_harness_files(&vendored_harness_root, &vendored_harness_root, &mut files)?;
        files.sort();
        for (name, path) in files {
            if store.contains(&name) {
                continue;
            }
            let contents = fs::read_to_string(&path).map_err(|err| {
                format!("failed to read vendored harness {}: {err}", path.display())
            })?;
            store.insert(
                name,
                format!("{contents}\n"),
                PreludeOrigin::VendoredHarness,
            );
        }
    }

    Ok(store)
}

pub fn materialize_test(
    case: &TestCase,
    preludes: &PreludeStore,
) -> Result<MaterializedTest, String> {
    if let Some(source) = rewrite_wasm_aot_self_contained(case) {
        return Ok(MaterializedTest {
            path: case.path.clone(),
            source,
            used_preludes: Vec::new(),
            negative: case.negative.clone(),
            is_module: case.is_module,
        });
    }

    let mut source = String::new();
    let mut used_preludes = Vec::new();

    if !case.flags.contains("raw") {
        if case.flags.contains("onlyStrict") {
            source.push_str("\"use strict\";\n");
        }

        let assert_prelude = preludes.get("assert.js");
        let use_trimmed_same_value_assert = assert_prelude
            .is_some_and(|prelude| can_use_wasm_aot_same_value_assert_prelude(case, prelude));
        let assert_needs_test262_error = !use_trimmed_same_value_assert
            && assert_prelude.is_some_and(|prelude| prelude.contents.contains("Test262Error"));
        let needs_full_sta = case_needs_full_sta_prelude(case);
        let needs_test262_error_preamble =
            assert_needs_test262_error || case_needs_test262_error_prelude(case);
        if needs_full_sta {
            if let Some(prelude) = preludes.get("sta.js") {
                source.push_str(&prelude.contents);
                used_preludes.push((prelude.name.clone(), prelude.origin));
            }
        } else if needs_test262_error_preamble {
            if let Some(prelude) = preludes
                .get("sta-preamble.js")
                .or_else(|| preludes.get("sta.js"))
            {
                source.push_str(&prelude.contents);
                used_preludes.push((prelude.name.clone(), prelude.origin));
            }
        }
        if let Some(prelude) = assert_prelude {
            if use_trimmed_same_value_assert {
                source.push_str(WASM_AOT_ASSERT_SAME_VALUE_PRELUDE);
            } else {
                source.push_str(&prelude.contents);
            }
            used_preludes.push((prelude.name.clone(), prelude.origin));
        }

        if case.flags.contains("async") {
            if let Some(prelude) = preludes.get("doneprintHandle.js") {
                source.push_str(&prelude.contents);
                source.push_str(TEST262_ASYNC_DONE_GUARD_PRELUDE);
                used_preludes.push((prelude.name.clone(), prelude.origin));
            }
        }

        for include in &case.includes {
            if include.is_empty() {
                continue;
            }
            if include == "testTypedArray.js" && wasm_aot_rewrite_skips_test_typed_array(&case.path)
            {
                continue;
            }
            if let Some(prelude) = preludes.get(include) {
                if include == "promiseHelper.js"
                    && case.path == "built-ins/AggregateError/order-of-args-evaluation.js"
                {
                    source.push_str(
                        "function checkSequence(arr, message) {\n  for (let i = 0; i < arr.length; i = i + 1) {\n    if (arr[i] !== i + 1) {\n      if (message !== undefined) throw new Test262Error(message);\n      throw new Test262Error(\"Steps in unexpected sequence:\");\n    }\n  }\n  return true;\n}\n",
                    );
                    used_preludes.push((prelude.name.clone(), prelude.origin));
                    continue;
                }
                if include == "nativeFunctionMatcher.js"
                    && case
                        .path
                        .starts_with("built-ins/Function/prototype/toString/")
                {
                    source.push_str(WASM_AOT_NATIVE_FUNCTION_MATCHER_PRELUDE);
                    used_preludes.push((prelude.name.clone(), prelude.origin));
                    continue;
                }
                source.push_str(&prelude.contents);
                used_preludes.push((prelude.name.clone(), prelude.origin));
            }
        }
    }

    source.push_str(&rewrite_wasm_aot_known_static_for_of(case));

    Ok(MaterializedTest {
        path: case.path.clone(),
        source,
        used_preludes,
        negative: case.negative.clone(),
        is_module: case.is_module,
    })
}

const WASM_AOT_ASSERT_SAME_VALUE_PRELUDE: &str = r#"
function __porfAssertToString(value) {
  if (value === undefined) {
    return 'undefined';
  }
  if (value === null) {
    return 'null';
  }
  return String(value);
}

function assert(mustBeTrue, message) {
  if (mustBeTrue) {
    return;
  }
  if (message === undefined) {
    message = 'Expected true but got false';
  }
  throw message;
}

assert.sameValue = function (actual, expected, message) {
  if (actual === expected) {
    return;
  }
  if (actual !== actual && expected !== expected) {
    return;
  }

  if (message === undefined) {
    message = '';
  } else {
    message = message + ' ';
  }

  message = message + 'Expected SameValue(' + __porfAssertToString(actual) + ', ' + __porfAssertToString(expected) + ') to be true';
  throw message;
};
"#;

const TEST262_ASYNC_DONE_GUARD_PRELUDE: &str = r#"
var __porfTest262AsyncDone = { active: true, called: false };
var __porfTest262OriginalDONE = $DONE;
$DONE = function $DONE(error) {
  if (__porfTest262AsyncDone.called) {
    throw new Error('host harness async $DONE called multiple times');
  }
  __porfTest262AsyncDone.called = true;
  return __porfTest262OriginalDONE(error);
};
globalThis.$DONE = $DONE;
"#;

const WASM_AOT_NATIVE_FUNCTION_MATCHER_PRELUDE: &str = r#"
function __porfValidateNativeFunctionSource(source, special) {
  if (typeof source !== "string") {
    throw "Conforms to NativeFunction Syntax: " + source;
  }

  var prefix = "function ";
  var suffix = "() { [native code] }";
  if (source.slice(0, prefix.length) !== prefix ||
      source.slice(source.length - suffix.length) !== suffix) {
    if (special === undefined) {
      throw "Conforms to NativeFunction Syntax: " + source;
    }
    throw "Conforms to NativeFunction Syntax: " + source + " (" + special + ")";
  }
}

const validateNativeFunctionSource = function(source) {
  __porfValidateNativeFunctionSource(source);
};

const assertToStringOrNativeFunction = function(fn, expected) {
  const actual = "" + fn;
  if (actual === expected) {
    return;
  }
  assertNativeFunction(fn, expected);
};

const assertNativeFunction = function(fn, special) {
  __porfValidateNativeFunctionSource("" + fn, special);
};
"#;

fn can_use_wasm_aot_same_value_assert_prelude(case: &TestCase, prelude: &PreludeEntry) -> bool {
    if prelude.origin != PreludeOrigin::LocalMerged
        || !prelude.contents.contains("__porfAssertToString")
        || !prelude.contents.contains("assert.sameValue")
    {
        return false;
    }
    if case.negative.is_some() || !case.includes.is_empty() {
        return false;
    }

    let source = case.original_source.as_str();
    source.contains("assert.sameValue")
        && !source.contains("assert.notSameValue")
        && !source.contains("assert.throws")
        && !source.contains("assert.compareArray")
        && !source.contains("compareArray(")
        && !source.contains("assert(")
        && !source.contains("assert._")
}

fn case_needs_test262_error_prelude(case: &TestCase) -> bool {
    case.original_source.contains("Test262Error") || case.original_source.contains("$DONOTEVALUATE")
}

fn case_needs_full_sta_prelude(case: &TestCase) -> bool {
    case.original_source.contains("$262")
        || case
            .includes
            .iter()
            .any(|include| include == "detachArrayBuffer.js")
}

