        assert!(harness.contains("__porfUnsupportedHost('AbstractModuleSource')"));
        assert!(harness.contains("__porfUnsupportedHost('IsHTMLDDA')"));
        assert!(harness.contains("__porfUnsupportedHost('detachArrayBuffer')"));
